public struct FfiDevice {
    public var fingerprint: String
    public var name: String
    public var trusted: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(fingerprint: String, name: String, trusted: Bool) {
        self.fingerprint = fingerprint
        self.name = name
        self.trusted = trusted
    }
}



extension FfiDevice: Equatable, Hashable {
    public static func ==(lhs: FfiDevice, rhs: FfiDevice) -> Bool {
        if lhs.fingerprint != rhs.fingerprint {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.trusted != rhs.trusted {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(fingerprint)
        hasher.combine(name)
        hasher.combine(trusted)
    }
}


